package app;

import app.auditlog.AuditLogRepository;
import app.auditlog.MemoryAuditLogRepository;
import app.category.CategoryRepository;
import app.category.MemoryCategoryRepository;
import app.customer.CustomerRepository;
import app.customer.MemoryCustomerRepository;
import app.order.MemoryOrderRepository;
import app.order.OrderRepository;
import app.orderline.MemoryOrderLineRepository;
import app.orderline.OrderLineRepository;
import app.product.MemoryProductRepository;
import app.product.ProductRepository;
import app.producttag.MemoryProductTagRepository;
import app.producttag.ProductTagRepository;
import app.tag.MemoryTagRepository;
import app.tag.TagRepository;
import java.util.function.Function;

/** The in-memory repositories, for tests and for trying the services without a database. */
public class MemoryUnitOfWork implements UnitOfWork {
    private final CustomerRepository customers = new MemoryCustomerRepository();
    private final CategoryRepository categories = new MemoryCategoryRepository();
    private final ProductRepository products = new MemoryProductRepository();
    private final OrderRepository orders = new MemoryOrderRepository();
    private final OrderLineRepository orderLines = new MemoryOrderLineRepository();
    private final TagRepository tags = new MemoryTagRepository();
    private final ProductTagRepository productTags = new MemoryProductTagRepository();
    private final AuditLogRepository auditLog = new MemoryAuditLogRepository();

    @Override
    public CustomerRepository customers() {
        return customers;
    }

    @Override
    public CategoryRepository categories() {
        return categories;
    }

    @Override
    public ProductRepository products() {
        return products;
    }

    @Override
    public OrderRepository orders() {
        return orders;
    }

    @Override
    public OrderLineRepository orderLines() {
        return orderLines;
    }

    @Override
    public TagRepository tags() {
        return tags;
    }

    @Override
    public ProductTagRepository productTags() {
        return productTags;
    }

    @Override
    public AuditLogRepository auditLog() {
        return auditLog;
    }

    /** Memory has no transactions: changes are kept as they are made. */
    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        return work.apply(this);
    }
}

