package app;

import app.auditlog.AuditLogRepository;
import app.auditlog.SqlAuditLogRepository;
import app.category.CategoryRepository;
import app.category.SqlCategoryRepository;
import app.customer.CustomerRepository;
import app.customer.SqlCustomerRepository;
import app.order.OrderRepository;
import app.order.SqlOrderRepository;
import app.orderline.OrderLineRepository;
import app.orderline.SqlOrderLineRepository;
import app.product.ProductRepository;
import app.product.SqlProductRepository;
import app.producttag.ProductTagRepository;
import app.producttag.SqlProductTagRepository;
import app.tag.SqlTagRepository;
import app.tag.TagRepository;
import jakarta.persistence.EntityManager;
import jakarta.persistence.EntityTransaction;
import java.util.function.Function;

/** The repositories over one EntityManager, and its transaction. */
public class SqlUnitOfWork implements UnitOfWork {
    private final EntityManager entityManager;
    private final CustomerRepository customers;
    private final CategoryRepository categories;
    private final ProductRepository products;
    private final OrderRepository orders;
    private final OrderLineRepository orderLines;
    private final TagRepository tags;
    private final ProductTagRepository productTags;
    private final AuditLogRepository auditLog;

    public SqlUnitOfWork(EntityManager entityManager) {
        this.entityManager = entityManager;
        this.customers = new SqlCustomerRepository(entityManager);
        this.categories = new SqlCategoryRepository(entityManager);
        this.products = new SqlProductRepository(entityManager);
        this.orders = new SqlOrderRepository(entityManager);
        this.orderLines = new SqlOrderLineRepository(entityManager);
        this.tags = new SqlTagRepository(entityManager);
        this.productTags = new SqlProductTagRepository(entityManager);
        this.auditLog = new SqlAuditLogRepository(entityManager);
    }

    public EntityManager entityManager() {
        return entityManager;
    }

    @Override
    public CustomerRepository customers() {
        return customers;
    }

    @Override
    public CategoryRepository categories() {
        return categories;
    }

    @Override
    public ProductRepository products() {
        return products;
    }

    @Override
    public OrderRepository orders() {
        return orders;
    }

    @Override
    public OrderLineRepository orderLines() {
        return orderLines;
    }

    @Override
    public TagRepository tags() {
        return tags;
    }

    @Override
    public ProductTagRepository productTags() {
        return productTags;
    }

    @Override
    public AuditLogRepository auditLog() {
        return auditLog;
    }

    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        EntityTransaction transaction = entityManager.getTransaction();
        // Joins the transaction already open
        if (transaction.isActive()) return work.apply(this);
        transaction.begin();
        try {
            T result = work.apply(this);
            transaction.commit();
            return result;
        } catch (RuntimeException error) {
            if (transaction.isActive()) transaction.rollback();
            throw error;
        }
    }
}

