import jakarta.persistence.EntityTransaction;
import java.util.ArrayList;
import java.util.List;

/** Keeps audit_log rows in the database, through an EntityManager. A write joins the transaction already open, or commits at once. */
public class SqlAuditLogRepository implements AuditLogRepository {
    protected final EntityManager entityManager;

    public SqlAuditLogRepository(EntityManager entityManager) {
        this.entityManager = entityManager;
    }

    @Override
    public CursorPage<AuditLog> list(List<Object> after, int limit) {
        String jpql = after == null ? "select e from AuditLog e order by e.at, e.message" : "select e from AuditLog e where ((e.at > :k0) or (e.at = :k0 and e.message > :k1)) order by e.at, e.message";
        var query = entityManager.createQuery(jpql, AuditLog.class).setMaxResults(limit + 1);
        if (after != null) query.setParameter("k0", after.get(0));
        if (after != null) query.setParameter("k1", after.get(1));
        List<AuditLog> rows = query.getResultList();
        List<AuditLog> items = new ArrayList<>(rows.subList(0, Math.min(limit, rows.size())));
        AuditLog last = items.isEmpty() ? null : items.get(items.size() - 1);
        return new CursorPage<>(items, rows.size() > limit ? List.of(last.getAt(), last.getMessage()) : null);
    }

    /** Runs a write in the transaction already open, or in one of its own. */
    private void inTransaction(Runnable write) {
        EntityTransaction transaction = entityManager.getTransaction();
        if (transaction.isActive()) {
            write.run();
            return;
        }
        transaction.begin();
        try {
            write.run();
            transaction.commit();
        } catch (RuntimeException error) {
            if (transaction.isActive()) transaction.rollback();
            throw error;
        }
    }
}

