/** Operations on categories. Each write runs in its own transaction. */
public class CategoryService {
    private final UnitOfWork uow;

    public CategoryService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "categories" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Category current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("name");
            if (value == null) {
                if (creating || values.containsKey("name")) errors.add(new FieldError("name", "is required"));
            } else {
                if (value instanceof String text && text.length() > 60) errors.add(new FieldError("name", "is longer than 60 characters"));
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Category", errors);
    }

    /** Values that must be unique are not taken by another row. */
    private void checkUnique(UnitOfWork uow, Map<String, Object> values, Category current) {
        {
            String name = (String) (values.containsKey("name") ? values.get("name") : current == null ? null : current.getName());
            if (name != null) {
                Optional<Category> other = uow.categories().findByName(name);
                if (other.isPresent() && (current == null || !Objects.equals(other.get().getId(), current.getId())))
                    throw new ConflictException("Category", "name is already taken", List.of("name"));
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Category current) {
        validate(uow, values, current);
        checkUnique(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(Category entity, Map<String, Object> values) {
        if (values.containsKey("name")) entity.setName((String) values.get("name"));
    }

    /** The Category with this key; NotFoundException when there is none. */
    private Category find(UnitOfWork uow, Long id) {
        return uow.categories().findById(id).orElseThrow(() -> new NotFoundException("Category", id));
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(CategoryChanges changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.name() != null) values.put("name", changes.name().orElse(null));
        return values;
    }

    /** Stores a new Category after checking it. */
    public Category createCategory(Category category) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (category.getName() != null) values.put("name", category.getName());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            return uow.categories().insert(category);
        });
    }

    /** The Category with this key; NotFoundException when there is none. */
    public Category getCategory(Long id) {
        return find(uow, id);
    }

    /** A page of categories after the key after (null for the first page), by primary key. */
    public CursorPage<Category> listCategories(List<Object> after, int limit) {
        return uow.categories().list(after, limit);
    }

    /** Changes the given values of a Category. */
    public Category updateCategory(Long id, CategoryChanges changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Category current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return uow.categories().update(current);
        });
    }

    /** Deletes a Category. */
    public void deleteCategory(Long id) {
        uow.transaction((uow) -> {
            Category current = find(uow, id);
            for (Product row : uow.products().listByCategoryId(current.getId())) uow.products().delete(row);
            uow.categories().delete(current);
            return null;
        });
    }

    /** The Category with this name, if there is one. */
    public Optional<Category> findCategoryByName(String name) {
        return uow.categories().findByName(name);
    }
}

