                .findFirst();
    }

    @Override
    public CursorPage<Category> list(List<Object> after, int limit) {
        String jpql = after == null ? "select e from Category e order by e.id" : "select e from Category e where (e.id > :k0) order by e.id";
        var query = entityManager.createQuery(jpql, Category.class).setMaxResults(limit + 1);
        if (after != null) query.setParameter("k0", after.get(0));
        List<Category> rows = query.getResultList();
        List<Category> items = new ArrayList<>(rows.subList(0, Math.min(limit, rows.size())));
        Category last = items.isEmpty() ? null : items.get(items.size() - 1);
        return new CursorPage<>(items, rows.size() > limit ? List.of(last.getId()) : null);
    }

    @Override
    public Optional<Category> findByName(String name) {
        return entityManager.createQuery("select e from Category e where e.name = :name", Category.class).setParameter("name", name)
                .getResultStream()
                .findFirst();
    }

    @Override
    public Category insert(Category entity) {
        try {
            inTransaction(() -> {
                entityManager.persist(entity);
                entityManager.flush();
                // Reads back what the database filled: the key, defaults
                entityManager.refresh(entity);
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Category", "the database refused the change: " + error.getMessage());
        }
        return entity;
    }

    @Override
    public Category update(Category entity) {
        Category[] stored = new Category[1];
        try {
            inTransaction(() -> {
                stored[0] = entityManager.merge(entity);
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Category", "the database refused the change: " + error.getMessage());
        }
        return stored[0];
    }

    @Override
    public void delete(Category entity) {
        try {
            inTransaction(() -> {
                entityManager.remove(entityManager.contains(entity) ? entity : entityManager.merge(entity));
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Category", "the database refused the change: " + error.getMessage());
        }
    }

    /** Runs a write in the transaction already open, or in one of its own. */
    private void inTransaction(Runnable write) {
