        if (after != null) query.setParameter("k0", after.get(0));
        List<Customer> rows = query.getResultList();
        List<Customer> items = new ArrayList<>(rows.subList(0, Math.min(limit, rows.size())));
        Customer last = items.isEmpty() ? null : items.get(items.size() - 1);
        return new CursorPage<>(items, rows.size() > limit ? List.of(last.getId()) : null);
    }

