                .getResultStream()
                .findFirst();
    }

    @Override
    public Customer insert(Customer entity) {
        try {
            inTransaction(() -> {
                entityManager.persist(entity);
                entityManager.flush();
                // Reads back what the database filled: the key, defaults
                entityManager.refresh(entity);
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Customer", "the database refused the change: " + error.getMessage());
        }
        return entity;
    }

    @Override
    public Customer update(Customer entity) {
        Customer[] stored = new Customer[1];
        try {
            inTransaction(() -> {
                stored[0] = entityManager.merge(entity);
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Customer", "the database refused the change: " + error.getMessage());
        }
        return stored[0];
    }

    @Override
    public void delete(Customer entity) {
        try {
            inTransaction(() -> {
                entityManager.remove(entityManager.contains(entity) ? entity : entityManager.merge(entity));
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Customer", "the database refused the change: " + error.getMessage());
        }
    }

    /** Runs a write in the transaction already open, or in one of its own. */
    private void inTransaction(Runnable write) {
        EntityTransaction transaction = entityManager.getTransaction();
        if (transaction.isActive()) {
            write.run();
            return;
        }
        transaction.begin();
        try {
            write.run();
