package app.order;

import app.UnitOfWork;
import app.common.CursorPage;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Operations on orders. Each write runs in its own transaction. */
public class OrderService {
    private final UnitOfWork uow;

    public OrderService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "orders" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Order current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("customerId");
            if (value == null) {
                if (creating || values.containsKey("customerId")) errors.add(new FieldError("customer_id", "is required"));
            }
        }
        {
            Long customerId = (Long) (values.containsKey("customerId") ? values.get("customerId") : current == null ? null : current.getCustomerId());
            if (customerId != null && uow.customers().findById(customerId).isEmpty())
                errors.add(new FieldError("customer_id", "no Customer has this key"));
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Order", errors);
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Order current) {
        validate(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(Order entity, Map<String, Object> values) {
        if (values.containsKey("customerId")) entity.setCustomerId((Long) values.get("customerId"));
    }

    /** The Order with this key; NotFoundException when there is none. */
    private Order find(UnitOfWork uow, Long id) {
        return uow.orders().findById(id).orElseThrow(() -> new NotFoundException("Order", id));
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(OrderChanges changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.customerId() != null) values.put("customerId", changes.customerId().orElse(null));
        return values;
    }

    /** Stores a new Order after checking it. */
    public Order createOrder(Order order) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (order.getCustomerId() != null) values.put("customerId", order.getCustomerId());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            return uow.orders().insert(order);
        });
    }

    /** The Order with this key; NotFoundException when there is none. */
    public Order getOrder(Long id) {
        return find(uow, id);
    }

    /** A page of orders after the key after (null for the first page), by primary key. */
    public CursorPage<Order> listOrders(List<Object> after, int limit) {
        return uow.orders().list(after, limit);
    }

    /** Changes the given values of a Order. */
    public Order updateOrder(Long id, OrderChanges changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Order current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return uow.orders().update(current);
        });
    }

    /** Deletes a Order. */
    public void deleteOrder(Long id) {
        uow.transaction((uow) -> {
            Order current = find(uow, id);
            uow.orders().delete(current);
            return null;
        });
    }

    /** The orders with this customer_id. */
    public List<Order> listOrdersByCustomerId(Long customerId) {
        return uow.orders().listByCustomerId(customerId);
    }
}

