    private void validate(UnitOfWork uow, Map<String, Object> values, OrderLine current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("orderId");
            if (value == null) {
                if (creating || values.containsKey("orderId")) errors.add(new FieldError("order_id", "is required"));
            }
        }
        {
            Object value = values.get("line");
            if (value == null) {
                if (creating || values.containsKey("line")) errors.add(new FieldError("line", "is required"));
            }
        }
        {
            Object value = values.get("productId");
            if (value == null) {
                if (creating || values.containsKey("productId")) errors.add(new FieldError("product_id", "is required"));
            }
        }
        {
            Object value = values.get("quantity");
            if (value == null) {
                if (creating || values.containsKey("quantity")) errors.add(new FieldError("quantity", "is required"));
            }
        }
        {
            Long orderId = (Long) (values.containsKey("orderId") ? values.get("orderId") : current == null ? null : current.getOrderId());
            if (orderId != null && uow.orders().findById(orderId).isEmpty())
