        }
        if (!errors.isEmpty()) throw new ValidationFailedException("OrderLine", errors);
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, OrderLine current) {
        validate(uow, values, current);
    }

