    private static void apply(OrderLine entity, Map<String, Object> values) {
        if (values.containsKey("orderId")) entity.setOrderId((Long) values.get("orderId"));
        if (values.containsKey("line")) entity.setLine((Integer) values.get("line"));
        if (values.containsKey("productId")) entity.setProductId((Long) values.get("productId"));
        if (values.containsKey("quantity")) entity.setQuantity((Integer) values.get("quantity"));
    }

