        if (changes.productId() != null) values.put("productId", changes.productId().orElse(null));
        if (changes.quantity() != null) values.put("quantity", changes.quantity().orElse(null));
        return values;
    }

    /** Stores a new OrderLine after checking it. */
    public OrderLine createOrderLine(OrderLine orderLine) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (orderLine.getOrderId() != null) values.put("orderId", orderLine.getOrderId());
        if (orderLine.getLine() != null) values.put("line", orderLine.getLine());
        if (orderLine.getProductId() != null) values.put("productId", orderLine.getProductId());
        if (orderLine.getQuantity() != null) values.put("quantity", orderLine.getQuantity());
        return uow.transaction((uow) -> {
