package app.orderline;

import app.common.CursorPage;
import app.errors.ConflictException;
import jakarta.persistence.EntityManager;
import jakarta.persistence.EntityTransaction;
import jakarta.persistence.PersistenceException;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/** Keeps order_lines rows in the database, through an EntityManager. A write joins the transaction already open, or commits at once. */
public class SqlOrderLineRepository implements OrderLineRepository {
    protected final EntityManager entityManager;

    public SqlOrderLineRepository(EntityManager entityManager) {
        this.entityManager = entityManager;
    }

    @Override
    public Optional<OrderLine> findByOrderIdAndLine(Long orderId, Integer line) {
        return entityManager.createQuery("select e from OrderLine e where e.orderId = :orderId and e.line = :line", OrderLine.class).setParameter("orderId", orderId).setParameter("line", line)
                .getResultStream()
                .findFirst();
    }

    @Override
    public CursorPage<OrderLine> list(List<Object> after, int limit) {
        String jpql = after == null ? "select e from OrderLine e order by e.orderId, e.line" : "select e from OrderLine e where ((e.orderId > :k0) or (e.orderId = :k0 and e.line > :k1)) order by e.orderId, e.line";
        var query = entityManager.createQuery(jpql, OrderLine.class).setMaxResults(limit + 1);
        if (after != null) query.setParameter("k0", after.get(0));
        if (after != null) query.setParameter("k1", after.get(1));
        List<OrderLine> rows = query.getResultList();
        List<OrderLine> items = new ArrayList<>(rows.subList(0, Math.min(limit, rows.size())));
        OrderLine last = items.isEmpty() ? null : items.get(items.size() - 1);
        return new CursorPage<>(items, rows.size() > limit ? List.of(last.getOrderId(), last.getLine()) : null);
    }

    @Override
    public List<OrderLine> listByOrderId(Long orderId) {
        return entityManager.createQuery("select e from OrderLine e where e.orderId = :orderId order by e.orderId, e.line", OrderLine.class).setParameter("orderId", orderId).getResultList();
    }

    @Override
    public List<OrderLine> listByProductId(Long productId) {
        return entityManager.createQuery("select e from OrderLine e where e.productId = :productId order by e.orderId, e.line", OrderLine.class).setParameter("productId", productId).getResultList();
    }

    @Override
    public OrderLine insert(OrderLine entity) {
        try {
            inTransaction(() -> {
                entityManager.persist(entity);
                entityManager.flush();
                // Reads back what the database filled: the key, defaults
                entityManager.refresh(entity);
            });
        } catch (PersistenceException error) {
            throw new ConflictException("OrderLine", "the database refused the change: " + error.getMessage());
        }
        return entity;
    }

    @Override
    public OrderLine update(OrderLine entity) {
        OrderLine[] stored = new OrderLine[1];
        try {
            inTransaction(() -> {
                stored[0] = entityManager.merge(entity);
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("OrderLine", "the database refused the change: " + error.getMessage());
        }
        return stored[0];
    }

    @Override
    public void delete(OrderLine entity) {
        try {
            inTransaction(() -> {
                entityManager.remove(entityManager.contains(entity) ? entity : entityManager.merge(entity));
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("OrderLine", "the database refused the change: " + error.getMessage());
        }
    }

    /** Runs a write in the transaction already open, or in one of its own. */
    private void inTransaction(Runnable write) {
        EntityTransaction transaction = entityManager.getTransaction();
        if (transaction.isActive()) {
            write.run();
            return;
        }
        transaction.begin();
        try {
            write.run();
            transaction.commit();
        } catch (RuntimeException error) {
            if (transaction.isActive()) transaction.rollback();
            throw error;
        }
    }
}

