package app.product;

import app.common.CursorPage;
import java.math.BigDecimal;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Stream;

/** Keeps products rows in memory, for tests and for trying the services without a database. */
public class MemoryProductRepository implements ProductRepository {
    private final Map<List<Object>, Product> rows = new LinkedHashMap<>();
    private long nextId = 1;

    /** The key of a row, as a list of its key values. */
    private static List<Object> keyOf(Product row) {
        List<Object> key = new ArrayList<>();
        key.add(row.getId());
        return key;
    }

    /** Orders two keys value by value. */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private static int compareKeys(List<Object> a, List<Object> b) {
        for (int index = 0; index < a.size(); index++) {
            int order = ((Comparable) a.get(index)).compareTo(b.get(index));
            if (order != 0) return order;
        }
        return 0;
    }

    private Stream<Product> visible() {
        return rows.values().stream().filter((row) -> true).sorted(Comparator.comparing(MemoryProductRepository::keyOf, MemoryProductRepository::compareKeys));
    }

    @Override
    public Optional<Product> findById(Long id) {
        return visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
    }

    @Override
    public CursorPage<Product> list(List<Object> after, int limit) {
        List<Product> rows = visible().filter((row) -> after == null || compareKeys(keyOf(row), after) > 0).toList();
        List<Product> items = rows.stream().limit(limit).toList();
        return new CursorPage<>(items, rows.size() > limit ? keyOf(items.get(items.size() - 1)) : null);
    }

    @Override
    public List<Product> listByCategoryId(Long categoryId) {
        return visible().filter((row) -> Objects.equals(row.getCategoryId(), categoryId)).toList();
    }

    @Override
    public List<Product> findAllByStatus(String status) {
        return visible().filter((row) -> Objects.equals(row.getStatus(), status)).toList();
    }

    @Override
    public Product insert(Product entity) {
        if (entity.getId() == null) entity.setId(nextId++);
        if (entity.getVersion() == null) entity.setVersion(1);
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public Product update(Product entity) {
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public void delete(Product entity) {
        rows.remove(keyOf(entity));
    }
}

