/** Operations on product_tags. Each write runs in its own transaction. */
public class ProductTagService {
    private final UnitOfWork uow;

    public ProductTagService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "product_tags" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, ProductTag current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("productId");
            if (value == null) {
                if (creating || values.containsKey("productId")) errors.add(new FieldError("product_id", "is required"));
            }
        }
        {
            Object value = values.get("tagId");
            if (value == null) {
                if (creating || values.containsKey("tagId")) errors.add(new FieldError("tag_id", "is required"));
            }
        }
        {
            Long productId = (Long) (values.containsKey("productId") ? values.get("productId") : current == null ? null : current.getProductId());
            if (productId != null && uow.products().findById(productId).isEmpty())
                errors.add(new FieldError("product_id", "no Product has this key"));
        }
        {
            Long tagId = (Long) (values.containsKey("tagId") ? values.get("tagId") : current == null ? null : current.getTagId());
            if (tagId != null && uow.tags().findById(tagId).isEmpty())
                errors.add(new FieldError("tag_id", "no Tag has this key"));
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("ProductTag", errors);
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, ProductTag current) {
        validate(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(ProductTag entity, Map<String, Object> values) {
        if (values.containsKey("productId")) entity.setProductId((Long) values.get("productId"));
        if (values.containsKey("tagId")) entity.setTagId((Long) values.get("tagId"));
    }

    /** The ProductTag with this key; NotFoundException when there is none. */
    private ProductTag find(UnitOfWork uow, Long productId, Long tagId) {
        return uow.productTags().findByProductIdAndTagId(productId, tagId).orElseThrow(() -> new NotFoundException("ProductTag", List.of(productId, tagId)));
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(ProductTagChanges changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        return values;
    }

    /** Stores a new ProductTag after checking it. */
    public ProductTag createProductTag(ProductTag productTag) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (productTag.getProductId() != null) values.put("productId", productTag.getProductId());
        if (productTag.getTagId() != null) values.put("tagId", productTag.getTagId());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            return uow.productTags().insert(productTag);
        });
    }

    /** The ProductTag with this key; NotFoundException when there is none. */
    public ProductTag getProductTag(Long productId, Long tagId) {
        return find(uow, productId, tagId);
    }

    /** A page of product_tags after the key after (null for the first page), by primary key. */
    public CursorPage<ProductTag> listProductTags(List<Object> after, int limit) {
        return uow.productTags().list(after, limit);
    }

    /** Changes the given values of a ProductTag. */
    public ProductTag updateProductTag(Long productId, Long tagId, ProductTagChanges changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            ProductTag current = find(uow, productId, tagId);
            check(uow, values, current);
            apply(current, values);
            return uow.productTags().update(current);
        });
    }

    /** Deletes a ProductTag. */
    public void deleteProductTag(Long productId, Long tagId) {
        uow.transaction((uow) -> {
            ProductTag current = find(uow, productId, tagId);
            uow.productTags().delete(current);
            return null;
        });
    }

    /** The product_tags with this product_id. */
    public List<ProductTag> listProductTagsByProductId(Long productId) {
        return uow.productTags().listByProductId(productId);
    }

    /** The product_tags with this tag_id. */
    public List<ProductTag> listProductTagsByTagId(Long tagId) {
        return uow.productTags().listByTagId(tagId);
    }
}

