package app.tag;

import app.UnitOfWork;
import app.common.CursorPage;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Operations on tags. Each write runs in its own transaction. */
public class TagService {
    private final UnitOfWork uow;

    public TagService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "tags" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Tag current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("label");
            if (value == null) {
                if (creating || values.containsKey("label")) errors.add(new FieldError("label", "is required"));
            } else {
                if (value instanceof String text && text.length() > 30) errors.add(new FieldError("label", "is longer than 30 characters"));
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Tag", errors);
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Tag current) {
        validate(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(Tag entity, Map<String, Object> values) {
        if (values.containsKey("label")) entity.setLabel((String) values.get("label"));
    }

    /** The Tag with this key; NotFoundException when there is none. */
    private Tag find(UnitOfWork uow, Long id) {
        return uow.tags().findById(id).orElseThrow(() -> new NotFoundException("Tag", id));
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(TagChanges changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.label() != null) values.put("label", changes.label().orElse(null));
        return values;
    }

    /** Stores a new Tag after checking it. */
    public Tag createTag(Tag tag) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (tag.getLabel() != null) values.put("label", tag.getLabel());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            return uow.tags().insert(tag);
        });
    }

    /** The Tag with this key; NotFoundException when there is none. */
    public Tag getTag(Long id) {
        return find(uow, id);
    }

    /** A page of tags after the key after (null for the first page), by primary key. */
    public CursorPage<Tag> listTags(List<Object> after, int limit) {
        return uow.tags().list(after, limit);
    }

    /** Changes the given values of a Tag. */
    public Tag updateTag(Long id, TagChanges changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Tag current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return uow.tags().update(current);
        });
    }

    /** Deletes a Tag. */
    public void deleteTag(Long id) {
        uow.transaction((uow) -> {
            Tag current = find(uow, id);
            uow.tags().delete(current);
            return null;
        });
    }
}

